    "# ==============================================================================\n",
    "# CELL 5: ZERO-LEAKAGE SPLIT, PIPELINING, PRICING MODEL & MASTER AUDIT\n",
    "# ==============================================================================\n",
    "numeric_features = [\"year\", \"mileage\", \"engine_capacity\", \"horsepower\", \"cylinder_count\", \"turbo_count\", \"car_age\", \"km_per_year\"]\n",
    "categorical_features = [\"brand\", \"body_type\", \"transmission\", \"fuel_type\", \"car_condition\", \"brand_tier\", \"drivetrain\"]\n",
    "\n",
    "numeric_features = [c for c in numeric_features if c in df.columns]\n",
    "categorical_features = [c for c in categorical_features if c in df.columns]\n",
    "\n",
    "X = df[numeric_features + categorical_features].copy()\n",
    "y = df[\"log_price\"].copy()\n",
    "prices_original = df[\"price\"].copy()\n",
    "\n",
    "# 1. التقسيم أولاً قبل أي معالجة إحصائية\n",
    "X_train, X_test, y_train, y_test, price_train, price_test = train_test_split(\n",
    "    X, y, prices_original, test_size=0.20, random_state=42\n",
    ")\n",
    "\n",
    "# 2. تحديد الفئات النادرة بناءً على Train فقط\n",
    "train_brand_counts = X_train[\"brand\"].value_counts()\n",
    "rare_train_brands = train_brand_counts[train_brand_counts < 10].index\n",
    "X_train[\"brand\"] = X_train[\"brand\"].where(~X_train[\"brand\"].isin(rare_train_brands), \"Other\")\n",
    "X_test[\"brand\"] = X_test[\"brand\"].where(~X_test[\"brand\"].isin(rare_train_brands), \"Other\")\n",
    "\n",
    "# 3. إعداد Pipeline المعالجة\n",
    "num_pipeline = Pipeline([\n",
    "    (\"imputer\", SimpleImputer(strategy=\"median\")),\n",
    "    (\"scaler\", StandardScaler())\n",
    "])\n",
    "\n",
    "cat_pipeline = Pipeline([\n",
    "    (\"imputer\", SimpleImputer(strategy=\"most_frequent\")),\n",
    "    (\"encoder\", OneHotEncoder(handle_unknown=\"ignore\", sparse_output=False))\n",
    "])\n",
    "\n",
    "preprocessor = ColumnTransformer([\n",
    "    (\"num\", num_pipeline, numeric_features),\n",
    "    (\"cat\", cat_pipeline, categorical_features)\n",
    "])\n",
    "\n",
    "# 4. بناء نموذج التقدير والتدريب\n",
    "price_model = HistGradientBoostingRegressor(max_iter=200, learning_rate=0.08, random_state=42)\n",
    "full_pricing_pipeline = Pipeline([\n",
    "    (\"preprocessor\", preprocessor),\n",
    "    (\"model\", price_model)\n",
    "])\n",
    "\n",
    "full_pricing_pipeline.fit(X_train, y_train)\n",
    "\n",
    "# 5. التقييم\n",
    "y_pred_log = full_pricing_pipeline.predict(X_test)\n",
    "y_pred_real = np.expm1(y_pred_log)\n",
    "\n",
    "r2_val = r2_score(y_test, y_pred_log)\n",
    "mae_val = mean_absolute_error(price_test, y_pred_real)\n",
    "rmse_val = root_mean_squared_error(price_test, y_pred_real)\n",
    "mape_val = mean_absolute_percentage_error(price_test, y_pred_real)\n",
    "\n",
    "print(\"*\" * 60)\n",
    "print(f\"  R² Score (Accuracy)         : {r2_val * 100:.2f}%\")\n",
    "print(f\"  Mean Absolute Error (MAE)   : {mae_val:,.2f} EGP\")\n",
    "print(f\"  Root Mean Squared Error     : {rmse_val:,.2f} EGP\")\n",
    "print(f\"  Mean Absolute Percentage    : {mape_val * 100:.2f}%\")\n",
    "print(\"*\" * 60)\n",
    "\n",
    "# 6. جدول التدقيق الموحد النهائي (Master Audit Table)\n",
    "audit_table = pd.DataFrame([\n",
